// ==================== src/components/Header.xuy ====================
write('src/components/Header.xuy', `import { div, a } from 'xunay'
import { route, go } from '@/router.xuy'

const LINKS = [
  { path: '/', label: '首页' },
  { path: '/demo', label: '示例' },
  { path: '/about', label: '关于' },
  { path: 'http://107.172.190.220:12342/', label: '文档', external: true },
  { path: 'http://107.172.190.220:12342/AI.spec', label: 'AI 文档', external: true }
]

export function Header() {
  return div({ class: 'header' },
    div({ class: 'brand', on: { click: () => go('/') } },
      div({ class: 'brand-logo' }),
      div({ class: 'brand-name' }, '${brandName}')
    ),
    div({ class: 'nav' },
      ...LINKS.map(link => link.external
        ? a({
            class: 'nav-link',
            href: link.path,
            target: '_blank'
          }, link.label)
        : a({
            class: () => 'nav-link' + (route() === link.path ? ' on' : ''),
            href: '#' + link.path,
            on: { click: () => go(link.path) }
          }, link.label)
      )
    )
  )
}
`)

write('src/components/Footer.xuy', `import { div, a } from 'xunay'

export function Footer() {
  return div({ class: 'footer' },
    a({ href: 'http://107.172.190.220:12342/', target: '_blank' }, '文档'),
    ' · ',
    a({ href: 'http://107.172.190.220:12342/AI.spec', target: '_blank' }, 'AI 文档'),
    ' · ',
    a({ href: 'https://github.com/xuanlie/xunay', target: '_blank' }, 'GitHub'),
    ' · Built with XuNay'
  )
}
`)

